@js:
var result = [];
var bigStyle = { "layout_flexGrow": 1, "layout_flexBasisPercent": 1 };
var uniformStyle = { "layout_flexGrow": 1, "layout_flexBasisPercent": 0.25 };

/* ===== 我的书架（对接书架API，自动遍历分页） ===== */
result.push({ "title": "我的书架", "url": "/api/bookcase.php?page=1", "style": bigStyle });

/* ===== 男生（大按钮）+ 子分类平铺 ===== */
result.push({ "title": "男生", "url": "/gender/boy/page/{{page}}/,{\"webView\":true}", "style": bigStyle });
var boySubs = [
  ["全部","/gender/boy/page/{{page}}/"],["玄幻","/gender/boy/category/1/page/{{page}}/"],
  ["奇幻","/gender/boy/category/2/page/{{page}}/"],["武侠","/gender/boy/category/3/page/{{page}}/"],
  ["仙侠","/gender/boy/category/4/page/{{page}}/"],["都市","/gender/boy/category/5/page/{{page}}/"],
  ["军事","/gender/boy/category/6/page/{{page}}/"],["历史","/gender/boy/category/7/page/{{page}}/"],
  ["游戏","/gender/boy/category/8/page/{{page}}/"],["体育","/gender/boy/category/9/page/{{page}}/"],
  ["科幻","/gender/boy/category/10/page/{{page}}/"],["诸天无限","/gender/boy/category/11/page/{{page}}/"],
  ["悬疑","/gender/boy/category/12/page/{{page}}/"]
];
for (var i = 0; i < boySubs.length; i++) {
  result.push({ "title": boySubs[i][0], "url": boySubs[i][1] + ',{\"webView\":true}', "style": uniformStyle });
}

/* ===== 女生（大按钮）+ 子分类平铺 ===== */
